import { defineCollection, reference } from 'astro:content';
import { glob, file } from 'astro/loaders';
import { z } from 'astro/zod';

const poll = z.object({
  question: z.string(),
  options: z.array(z.string()).min(2).max(8),
});

/** RSS-owned episode data, regenerated by `npm run sync`. Don't edit by hand. */
const feed = defineCollection({
  loader: file('src/data/feed.json', { parser: (text) => JSON.parse(text).episodes.map((e: { slug: string }) => ({ id: e.slug, ...e })) }),
  schema: z.object({
    guid: z.string(),
    number: z.number(),
    slug: z.string(),
    title: z.string(),
    description: z.string(),
    published: z.coerce.date(),
    duration: z.number(),
    audio: z.object({ url: z.string(), type: z.string(), bytes: z.number() }),
    link: z.string(),
    image: z.string().nullable(),
    explicit: z.boolean(),
  }),
});

/** Your additions to each episode, one .md per episode (stubs are created by `npm run sync`). */
const episodes = defineCollection({
  loader: glob({ pattern: '*.md', base: 'src/content/episodes' }),
  schema: z.object({
    guid: z.string(),
    /** Show this instead of Spotify's title/description (set from the site). Markdown-lite description. */
    title: z.string().optional(),
    description: z.string().optional(),
    /** Defaults to every host in src/content/people. */
    participants: z.array(reference('people')).optional(),
    guests: z.array(z.object({ name: z.string(), url: z.string().optional() })).default([]),
    movies: z.array(reference('movies')).default([]),
    chapters: z.array(z.object({ start: z.number(), title: z.string() })).default([]),
    poll: poll.optional(),
    youtube: z.string().optional(),
  }),
});

const transcripts = defineCollection({
  loader: glob({ pattern: '*.json', base: 'src/content/transcripts' }),
  schema: z.object({
    episode: z.string(),
    /** tracks: one file per person (exact). diarized: speakers detected from the mix. mixed: no speakers. */
    source: z.enum(['tracks', 'diarized', 'mixed']),
    model: z.string(),
    generated: z.string(),
    segments: z.array(
      z.object({ s: z.number(), e: z.number(), sp: z.string().nullable(), t: z.string() }),
    ),
  }),
});

const movies = defineCollection({
  loader: glob({ pattern: '*.md', base: 'src/content/movies' }),
  schema: ({ image }) =>
    z.object({
      title: z.string(),
      year: z.number().optional(),
      director: z.string().optional(),
      runtime: z.number().optional(),
      genres: z.array(z.string()).default([]),
      poster: image().optional(),
      tmdbId: z.number().optional(),
      synopsis: z.string().optional(),
      verdicts: z
        .record(z.string(), z.object({ rating: z.number().min(0).max(10).optional(), take: z.string().optional() }))
        .default({}),
      quotes: z.array(z.object({ episode: z.string(), start: z.number(), end: z.number().optional() })).default([]),
      poll: poll.optional(),
      /** Added by `npm run find-movies` because it was mentioned (not necessarily discussed). */
      auto: z.boolean().default(false),
      /** Take it off the movie list (hosts can also do this from the site). */
      hidden: z.boolean().default(false),
      aliases: z.array(z.string()).default([]),
    }),
});

const people = defineCollection({
  loader: glob({ pattern: '*.md', base: 'src/content/people' }),
  schema: ({ image }) =>
    z.object({
      name: z.string(),
      short: z.string(),
      role: z.string().default('Co-host'),
      order: z.number().default(0),
      photo: image().optional(),
      favorites: z.array(z.string()).default([]),
      links: z.array(z.object({ label: z.string(), url: z.string() })).default([]),
    }),
});

export const collections = { feed, episodes, transcripts, movies, people };
